<div class="section-heading"><h1>Usuarios</h1><a class="button" href="<?= e(url('admin/usuarios/nuevo')) ?>">Crear usuario</a></div><form class="filters" method="get"><div class="field"><label for="user-q">Buscar nombre o correo</label><input id="user-q" type="search" name="q" value="<?= e($q) ?>"></div><?php if ($trash): ?><input type="hidden" name="trash" value="1"><?php endif; ?><button class="button">Buscar usuarios</button><a class="button button--quiet" href="<?= e(url('admin/usuarios') . ($trash ? '' : '?trash=1')) ?>"><?= $trash ? 'Usuarios actuales' : 'Ver papelera' ?></a></form><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de usuarios, desplazable"><table><caption>Usuarios <?= $trash ? 'en papelera' : 'registrados' ?></caption><thead><tr><th scope="col">Nombre y correo</th><th scope="col">Rol</th><th scope="col">Estado</th><th scope="col">Acciones</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= e($item['name']) ?><small><?= e($item['email']) ?></small></td><td><?= e($item['role']) ?></td><td><?= $item['active'] ? 'Activo' : 'Desactivado' ?></td><td><?php if (!$trash): ?><a class="button button--quiet" href="<?= e(url('admin/usuarios/' . $item['id'] . '/editar')) ?>">Editar<span class="sr-only"> <?= e($item['name']) ?></span></a><?php endif; ?><form method="post" action="<?= e(url('admin/usuarios/' . $item['id'] . ($trash ? '/restaurar' : '/eliminar'))) ?>"<?= !$trash ? ' data-confirm' : '' ?>><?= csrf() ?><?php if (!$trash): ?><label class="check"><input name="confirm" type="checkbox" value="1" required> Confirmo eliminar <?= e($item['name']) ?></label><?php endif; ?><button class="button <?= !$trash ? 'button--danger' : '' ?>"><?= $trash ? 'Restaurar' : 'Eliminar' ?><span class="sr-only"> <?= e($item['name']) ?></span></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php pagination($result, 'admin/usuarios', ['q' => $q, 'trash' => $trash ? '1' : '0']); ?>
